#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n;scanf("%d",&n);vector<long long>a(n);
for(int i=0;i<n;++i)scanf("%lld",&a[i]);
long long total=0,cur=0;
for(int i=2;i<n;++i){
if(a[i]-a[i-1]==a[i-1]-a[i-2]){++cur;total+=cur;}
else cur=0;}
printf("%lld\n",total);return 0;}

